import * as fs from "node:fs";
import type { Sql } from "postgres";

export async function deleteDisposableUser(db: Sql, user: string) {
  await db.begin(async tx => {
    await tx`select set_config('request.jwt.claim.sub', ${user}, true)`;
    await tx`select public.reset_workspace()`;
    await tx`delete from public.workspace_settings where workspace_id in (select id from public.workspaces where owner_id = ${user})`;
    await tx`delete from public.categories where workspace_id in (select id from public.workspaces where owner_id = ${user})`;
    await tx`delete from public.workspaces where owner_id = ${user}`;
    await tx`delete from auth.users where id = ${user}`;
  });
}

}

export function hasSupabaseEnv(): boolean {
  return Boolean(
    process.env.NEXT_PUBLIC_SUPABASE_URL &&
      process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY,
  );
}

export function e2eStorageStatePath(): string | null {
  const candidate = process.env.E2E_STORAGE_STATE;
  if (candidate && fs.existsSync(candidate)) return candidate;
  const fallback = "e2e/.auth.json";
  return fs.existsSync(fallback) ? fallback : null;
}

export function gatedSkipReason(): string {
  const missing: string[] = [];
  if (!process.env.NEXT_PUBLIC_SUPABASE_URL)
    missing.push("NEXT_PUBLIC_SUPABASE_URL");
  if (!process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY)
    missing.push("NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY");
  if (!e2eStorageStatePath())
    missing.push("E2E_STORAGE_STATE (or e2e/.auth.json storageState)");
  return (
    `Skipped: full authenticated Supabase journey needs ${missing.join(", ")}. ` +
    `This is a SKIP, not a pass — see e2e/README.md §2. ` +
    `Credential-free specs (smoke + mocked import journey) still run.`
  );
}
import { expect, test, type Locator, type Page } from "@playwright/test";
import { createClient } from "@supabase/supabase-js";
import { createServerClient } from "@supabase/ssr";
import { randomBytes, randomUUID } from "node:crypto";
import { mkdirSync, writeFileSync, unlinkSync } from "node:fs";
import postgres from "postgres";

test.skip(!process.env.SUPABASE_DB_URL || !process.env.SUPABASE_SERVICE_ROLE_KEY || !process.env.NEXT_PUBLIC_SUPABASE_URL || !process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY, "Requires real disposable Supabase authentication");

type RGB = [number, number, number];

async function probeColors(page: Page, target: Locator): Promise<{ fg: RGB; bg: RGB }> {
  return target.evaluate((element) => {
    const canvas = document.createElement("canvas");
    canvas.width = 1; canvas.height = 1;
    const ctx = canvas.getContext("2d", { willReadFrequently: true })!;
    const read = (css: string): [number, number, number, number] => {
      ctx.clearRect(0, 0, 1, 1);
      ctx.fillStyle = "#010203";
      ctx.fillStyle = css;
      ctx.fillRect(0, 0, 1, 1);
      const [r, g, b, a] = ctx.getImageData(0, 0, 1, 1).data;
      if (r === 1 && g === 2 && b === 3) throw new Error(`canvas could not resolve color: ${css}`);
      return [r, g, b, a / 255];
    };
    const over = (top: [number, number, number, number], bottom: RGB): RGB => {
      const a = top[3];
      return [top[0] * a + bottom[0] * (1 - a), top[1] * a + bottom[1] * (1 - a), top[2] * a + bottom[2] * (1 - a)];
    };
    const chain: string[] = [];
    let node: Element | null = element;
    while (node) {
      chain.push(getComputedStyle(node).backgroundColor);
      node = node.parentElement;
    }
    let bg: RGB = [255, 255, 255];
    for (let i = chain.length - 1; i >= 0; i--) bg = over(read(chain[i]), bg);
    return { fg: over(read(getComputedStyle(element).color), bg), bg };
  });
}

function ratio(fg: RGB, bg: RGB): number {
  const luminance = ([r, g, b]: RGB) => {
    const f = (v: number) => {
      const s = v / 255;
      return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
    };
    return 0.2126 * f(r) + 0.7152 * f(g) + 0.0722 * f(b);
  };
  const a = luminance(fg), b = luminance(bg);
  return (Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05);
}

async function expectReadable(page: Page, target: Locator, label: string) {
  const { fg, bg } = await probeColors(page, target);
  const value = ratio(fg, bg);
  const theme = await page.locator("html").getAttribute("data-theme");
  expect(value, `${label} [theme=${theme}]: rgb(${fg.map(Math.round)}) on rgb(${bg.map(Math.round)}) = ${value.toFixed(2)}:1`).toBeGreaterThanOrEqual(4.5);
}

