  await page.route("**/api/imports", (route) => route.fulfill({ json: [queued] }));
  await page.route(\`**/api/imports/\${id}\`, (route) => route.fulfill({ json: ++polls === 1 ? { ...queued, status: "running", new_rows: 25 } : queued }));
